examples.template:
LazyVGrid(columns: [GridItem(.adaptive(minimum: 140), spacing: 8)], spacing: 8) {
    MonarchCallTile({{tiles.0.name}}, isSelf: {{tiles.0.self}}, isMicOff: {{tiles.0.micOff}})
    MonarchCallTile({{tiles.1.name}}, isSpeaking: {{tiles.1.speaking}}, quality: {{tiles.1.quality|case}})
    MonarchCallTile({{tiles.2.name}}, isHandRaised: {{tiles.2.handRaised}}, quality: {{tiles.2.quality|case}})
    MonarchCallTile({{tiles.3.name}}, status: {{tiles.3.status}}, statusTone: {{tiles.3.statusTone|tone}}, quality: {{tiles.3.quality|case}})
}

examples.code:
LazyVGrid(columns: [GridItem(.adaptive(minimum: 140), spacing: 8)], spacing: 8) {
