    MonarchCallTile("Robin Park", isSpeaking: true, quality: .good)
    MonarchCallTile("Alex Chen", isHandRaised: true, quality: .fair)
    MonarchCallTile("Jordan Diaz", status: "Reconnecting…", statusTone: .warning, quality: .poor)
}

